package com.oms.supplychain;

import com.oms.supplychain.service.wms.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.supplychain.PurchaseWorkspaceTest.*;

class SupplychainIterationTest {
    PurchaseWorkspaceTest f;PurchaseReceiptDifferences differences;SupplychainOperations operations;
    @BeforeAll static void start(){PurchaseWorkspaceTest.init();}
    @AfterAll static void stop(){PurchaseWorkspaceTest.shutdown();}
    @BeforeEach void setup(){f=new PurchaseWorkspaceTest();f.seed();differences=context.getBean(PurchaseReceiptDifferences.class);operations=new SupplychainOperations();org.springframework.test.util.ReflectionTestUtils.setField(operations,"db",context.getBean(WmsStore.class));}
    long po(long ticket){return db.queryForObject("SELECT p.id FROM po_info p JOIN wms_tickets t ON t.company_key=p.company_key AND t.original_sn=p.po_sn WHERE t.id=?",Long.class,ticket);}
    Map<String,Object> difference(long ticket,String kind){return db.queryForMap("SELECT * FROM purchase_receipt_difference WHERE ticket_id=? AND difference_kind=?",ticket,kind);}
    Map<String,Object> command(Map<String,Object> d,String decision){return m("control_version",d.get("control_version"),"decision",decision,"reason","verified original warehouse evidence");}
    @SuppressWarnings("unchecked") Map<String,Object> journey(long p){return (Map<String,Object>)service.detail("QM","purchase",p).get("journey");}
    long n(Object value){return ((Number)value).longValue();}
    @Test void plannedScheduledReceivedAndPostedRemainSeparate(){long t=f.realTicket(10);f.accepted(t);f.inbound().accept("QM",f.inbound().task("QM",t),f.confirmation(t,"PARTIAL",4,0,false));Map<String,Object> summary=journey(po(t));assertEquals(10,n(summary.get("planned")));assertEquals(4,n(summary.get("confirmed")));assertEquals(0,n(summary.get("posted")));assertEquals(4,n(summary.get("unposted")));assertEquals(6,n(summary.get("unreceived")));assertTrue(f.inbound().post("QM",t));assertEquals(4,n(journey(po(t)).get("posted")));}
    @Test void unapprovedArrivalStillCountsAsArrangedAwaitingReceipt(){long p=f.purchase(f.line("A",100,"2.50"));service.approve("QM",p,"tester");f.receipt(p,60);Map<String,Object> j=journey(p);assertEquals(60,n(j.get("scheduled")));assertEquals(40,n(j.get("unarranged")));assertEquals(60,n(j.get("unreceived")));}
    @Test void duplicateOverReceiptIsRetainedOnceWithoutStock(){long t=f.realTicket(5);f.accepted(t);WmsProtocol.Receipt fact=f.confirmation(t,"OVER",7,0,true);for(int i=0;i<2;i++)assertThrows(IllegalArgumentException.class,()->f.inbound().accept("QM",f.inbound().task("QM",t),fact));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_receipt_difference",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM wms_receipt_event",Integer.class));assertEquals(0,calls.get());assertEquals(2,n(difference(t,"OVER").get("difference_quantity")));}
    @Test void signedIdentityMismatchDoesNotCreateABusinessDifference(){long t=f.realTicket(5);f.accepted(t);WmsProtocol.Receipt fact=f.confirmation(t,"FOREIGN",7,0,true);fact.owner="OTHER";assertThrows(IllegalArgumentException.class,()->f.inbound().accept("QM",f.inbound().task("QM",t),fact));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM purchase_receipt_difference",Integer.class));}
    @Test void wrongSkuIsQuarantinedUntilOriginalMessageIsCorrected(){long t=f.realTicket(5);f.accepted(t);WmsProtocol.Receipt fact=f.confirmation(t,"CORRECT",5,0,true);fact.lines.get(0).sku="B";assertThrows(IllegalArgumentException.class,()->f.inbound().accept("QM",f.inbound().task("QM",t),fact));assertEquals("OPEN",difference(t,"WRONG_SKU").get("state"));fact.lines.get(0).sku="A";f.inbound().accept("QM",f.inbound().task("QM",t),fact);assertTrue(f.inbound().post("QM",t));assertEquals("CORRECTED",difference(t,"WRONG_SKU").get("state"));assertEquals(5,n(journey(po(t)).get("posted")));}
    @Test void finalShortageCanCreateOnlyOneSupplementalArrival(){long t=f.realTicket(10);f.accepted(t);f.inbound().accept("QM",f.inbound().task("QM",t),f.confirmation(t,"SHORT",8,0,true));assertTrue(f.inbound().post("QM",t));Map<String,Object> d=difference(t,"SHORT");Map<String,Object> result=differences.decide("QM",n(d.get("id")),command(d,"REARRANGE"),"reviewer");assertNotNull(result.get("receipt_id"));assertEquals(2,db.queryForObject("SELECT number_expected FROM no_tickets WHERE id=?",Integer.class,result.get("receipt_id")));assertEquals(8,n(journey(po(t)).get("posted")));assertEquals(0,n(journey(po(t)).get("unarranged")));assertThrows(IllegalArgumentException.class,()->differences.decide("QM",n(d.get("id")),command(d,"REARRANGE"),"reviewer"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM no_tickets",Integer.class));}
    @Test void shortReceiptCannotRearrangeBeforePostingSucceeds(){long t=f.realTicket(10);f.accepted(t);f.inbound().accept("QM",f.inbound().task("QM",t),f.confirmation(t,"SHORT",8,0,true));Map<String,Object> d=difference(t,"SHORT");assertThrows(IllegalArgumentException.class,()->differences.decide("QM",n(d.get("id")),command(d,"REARRANGE"),"reviewer"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM no_tickets",Integer.class));}
    @Test void badGoodsAreTrackedSeparatelyAndDispositionDoesNotPostAgain(){long t=f.realTicket(5);f.accepted(t);f.inbound().accept("QM",f.inbound().task("QM",t),f.confirmation(t,"BAD",3,2,true));Map<String,Object> d=difference(t,"QUALITY");assertThrows(IllegalArgumentException.class,()->differences.decide("QM",n(d.get("id")),command(d,"KEEP_BAD"),"reviewer"));assertTrue(f.inbound().post("QM",t));int before=calls.get();differences.decide("QM",n(d.get("id")),command(d,"KEEP_BAD"),"reviewer");assertEquals(before,calls.get());assertEquals(2,n(journey(po(t)).get("bad")));assertEquals("RESOLVED",difference(t,"QUALITY").get("state"));}
    @Test void exceptionWorkbenchGroupsDocumentReasonsAndDropsResolvedIssues(){long t=f.realTicket(5);f.accepted(t);db.update("UPDATE wms_inbound_task SET last_query_result='FAILED',query_message='query failed' WHERE ticket_id=?",t);String sn=db.queryForObject("SELECT sn FROM wms_tickets WHERE id=?",String.class,t);Map<String,String> q=new HashMap<>();q.put("number",sn);q.put("issue","QUERY");assertEquals(1,n(operations.query("QM",q).get("total")));assertEquals(0,n(operations.query("OTHER",q).get("total")));db.update("UPDATE wms_inbound_task SET last_query_result='SUCCESS' WHERE ticket_id=?",t);assertEquals(0,n(operations.query("QM",q).get("total")));assertEquals("ACCEPTED",f.inbound().task("QM",t).get("dispatch_state"));}
    @Test void differenceVersionAndCompanyAreCheckedBeforeResolution(){long t=f.realTicket(5);f.accepted(t);WmsProtocol.Receipt fact=f.confirmation(t,"OVER",6,0,true);assertThrows(IllegalArgumentException.class,()->f.inbound().accept("QM",f.inbound().task("QM",t),fact));Map<String,Object>d=difference(t,"OVER");assertThrows(IllegalArgumentException.class,()->differences.detail("OTHER",n(d.get("id"))));Map<String,Object> stale=command(d,"REJECT");stale.put("control_version",0);assertThrows(IllegalArgumentException.class,()->differences.decide("QM",n(d.get("id")),stale,"tester"));differences.decide("QM",n(d.get("id")),command(d,"REJECT"),"tester");assertEquals(0,calls.get());}
    @Test void invalidWorkbenchFiltersAreRejected(){assertThrows(IllegalArgumentException.class,()->operations.query("QM",Collections.singletonMap("pageSize","51")));assertThrows(IllegalArgumentException.class,()->operations.query("QM",Collections.singletonMap("issue","BAD")));}
    @Test void warehouseStateAndLatestInteractionFiltersAreIndependent(){long t=f.realTicket(5);f.accepted(t);db.update("INSERT INTO wms_interaction_log(company_code,connection_id,ticket_sn,action,direction,result,request_id,request_body) SELECT company_code,connection_id,ticket_sn,'QUERY','OUT','FAILED','ITER_QUERY','' FROM wms_inbound_task WHERE ticket_id=?",t);Map<String,Object> q=m("sn",service.detail("QM","ticket",t).get("sn"),"warehouseState","ACCEPTED","warehouseResult","FAILED");assertEquals(1,service.page("QM","ticket",q,1,20).getTotal());q.put("warehouseState","FAILED");assertEquals(0,service.page("QM","ticket",q,1,20).getTotal());}
    @Test void procurementUnitsAreSnapshottedAndNeverAddedIntoOneNamedUnit(){long p=f.purchase(f.line("A",2,"2.50"),f.line("B",1,"5"));db.update("UPDATE purchase_line SET stock_unit='套' WHERE po_sn=(SELECT po_sn FROM po_info WHERE id=?) AND sku_sn='B'",p);List<Map<String,Object>> units=(List<Map<String,Object>>)journey(p).get("units");assertEquals(2,units.size());assertEquals(2,n(units.get(0).get("planned")));assertEquals(1,n(units.get(1).get("planned")));}
    @Test void concurrentShortageReviewsCreateOneArrival() throws Exception {long t=f.realTicket(10);f.accepted(t);f.inbound().accept("QM",f.inbound().task("QM",t),f.confirmation(t,"SHORT_CONCURRENT",8,0,true));assertTrue(f.inbound().post("QM",t));Map<String,Object>d=difference(t,"SHORT");ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<2;i++)results.add(pool.submit(()->{try{differences.decide("QM",n(d.get("id")),command(d,"REARRANGE"),"reviewer");return true;}catch(IllegalArgumentException changed){return false;}}));int accepted=0;for(Future<Boolean> result:results)if(result.get(20,TimeUnit.SECONDS))accepted++;assertEquals(1,accepted);assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM no_tickets",Integer.class));}finally{pool.shutdownNow();}}
}
